import { readFileSync, writeFileSync } from 'node:fs'
import { dirname, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'
import { COLOURS, TOKENS } from '../src/palette/palette.ts'

const OUTPUT_PATH = resolve(
  dirname(fileURLToPath(import.meta.url)),
  '../src/palette.css'
)
const HEADER =
  '/* Generated by scripts/generate-palette.ts from src/palette/palette.ts. Do not edit. */'
const CHECK_FLAG = '--check'
const HEX_PATTERN = /^#[0-9a-f]{6}$/

function declarations(entries: [string, string][]): string {
  return entries.map(([name, value]) => `  --${name}: ${value};`).join('\n')
}

function validatePalette(): void {
  const names = COLOURS.map((colour) => colour.name)
  const nameSet = new Set(names)
  if (nameSet.size !== names.length) throw new Error('duplicate colour name')
  for (const colour of COLOURS) {
    if (!HEX_PATTERN.test(colour.hex))
      throw new Error(`${colour.name}: ${colour.hex} is not a lowercase hex`)
    if ('derivedFrom' in colour && !nameSet.has(colour.derivedFrom))
      throw new Error(`${colour.name}: unknown parent ${colour.derivedFrom}`)
  }
  const tokenNames = TOKENS.map((token) => token.name)
  if (new Set(tokenNames).size !== tokenNames.length)
    throw new Error('duplicate token name')
}

function buildPaletteCss(): string {
  const named = declarations(COLOURS.map((c) => [c.name, c.hex]))
  const light = declarations(TOKENS.map((t) => [t.name, `var(--${t.light})`]))
  const dark = declarations(TOKENS.map((t) => [t.name, `var(--${t.dark})`]))
  return (
    [
      HEADER,
      `:root,\n.light {\n${named}\n}`,
      `:root,\n.light {\n${light}\n}`,
      `.dark {\n${dark}\n}`,
    ].join('\n\n') + '\n'
  )
}

validatePalette()
const css = buildPaletteCss()

if (process.argv.includes(CHECK_FLAG)) {
  let onDisk = ''
  try {
    onDisk = readFileSync(OUTPUT_PATH, 'utf8')
  } catch {
    onDisk = ''
  }
  if (onDisk !== css) {
    console.error('src/palette.css is out of date. Run `pnpm palette`.')
    process.exit(1)
  }
  console.log('src/palette.css is up to date.')
} else {
  writeFileSync(OUTPUT_PATH, css)
  console.log(`Wrote ${OUTPUT_PATH}`)
}
